'use strict';
(() => {
const D=window.OBS_DATA, $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), norm=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const paths={leaf:'M20 4C10 2 3 6 4 14c1 8 13 8 16-10ZM4 20 16 8M9 15v-5m0 5h5',home:'m3 11 9-8 9 8M5 10v11h5v-7h4v7h5V10',chart:'M4 20V10h4v10m4 0V4h4v16m4 0V7M2 21h20',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16m6-14v16',bird:'m3 15 4-1 5-7 3 2 4-1 2 3-3 1-2 6-6 2H4l4-5M12 20v2m3-3v3',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3ZM12 6v15',people:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3m20 0v-3a4 4 0 0 0-3-4M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8m8 0a4 4 0 0 1 0 8',info:'M12 8h.01M12 11v6M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',arrow:'M4 12h16m-6-6 6 6-6 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',water:'M12 2S4 11 4 15a8 8 0 0 0 16 0c0-4-8-13-8-13ZM8 15c0 2 1 3 3 3',sun:'M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M17 12a5 5 0 1 1-10 0 5 5 0 0 1 10 0',menu:'M3 6h18M3 12h18M3 18h18',file:'M5 2h9l5 5v15H5ZM14 2v6h5M8 12h8m-8 4h8',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',sound:'m3 9 4 0 5-5v16l-5-5H3ZM16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14'};
const icon=n=>`<svg class="obs-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.leaf}"/></svg>`;
const nav=[['inicio','Inicio','home'],['paneles','Paneles por tema','chart'],['indicadores','Indicadores','chart'],['mapas','Mapas del territorio','map'],['biodiversidad','Biodiversidad','bird'],['descargas','Panel de descargas','download'],['biblioteca','Documentación','book'],['reportes','Reportes y boletines','file'],['participa','Participa y aprende','people'],['acerca','Sobre el observatorio','info']];
let docSection='todos';let panelTopic='';let territory='comuna22',route='inicio',indPage=1,bioPage=1,bioTab='resumen',mapZoom=100;
const territoryName=()=>territory==='comuna22'?'Comuna 22':'Corregimiento La Buitrera';
const doc=(term,t=territory)=>D.documents.find(d=>d.territory===t&&norm(d.title).includes(norm(term)));
const source=(term,page,t=territory)=>{const d=doc(term,t);return d?`<a href="${d.file}${page?'#page='+page:''}" target="_blank" rel="noopener">${esc(d.title)}${page?' · p. '+page:''}</a>`:''};
const btn=(text,href,cls='',ic='arrow')=>`<a class="btn ${cls}" href="${href}">${esc(text)}${icon(ic)}</a>`;
const head=(title,sub,extra='')=>`<div class="pagehead"><div><span class="eyebrow">${territoryName()}</span><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`;
const notice=(text,amber=false)=>`<div class="notice ${amber?'amber':''}">${text}</div>`;
const nfmt=(n,d=1)=>Number(n).toLocaleString('es-CO',{maximumFractionDigits:d});
const mainIndicators=[
 {id:'c-crecimiento',name:'Crecimiento urbano',topic:'Ordenamiento territorial',kind:'Presión',value:'23,7 %',period:'2025 · superficie construida',unit:'Porcentaje y hectáreas',description:'Muestra cuánto suelo de la comuna está ocupado por edificaciones.',meaning:'En 2025 se reportan 254,2 hectáreas construidas. El crecimiento transforma el paisaje y aumenta la presión sobre humedales y corredores ambientales.',method:'Área construida / área total de la comuna × 100. Interpretación multitemporal de imágenes y cartografía.',limit:'Las imágenes tienen resoluciones distintas. Pequeñas variaciones entre cortes no demuestran por sí solas recuperación ambiental.',action:'Observa los cambios del paisaje y participa en recorridos de lectura del territorio.',doc:'Resultado de Componente OT',page:1,map:'crecimiento',series:[['2001',10.1],['2012',20.3],['2016',21.2],['2020',23.8],['2023',23.6],['2025',23.7]],max:30,ic:'home'},
 {id:'c-impermeable',name:'Impermeabilización del suelo',topic:'Ordenamiento territorial',kind:'Presión',value:'34,5 %',period:'2025 · 370,3 hectáreas',unit:'Porcentaje y hectáreas',description:'Indica la proporción del suelo cubierta por superficies que dificultan la infiltración del agua.',meaning:'Las construcciones y superficies pavimentadas reducen la capacidad del suelo para absorber agua. El informe registra 370,3 hectáreas impermeabilizadas en 2025.',method:'Área de superficies impermeables / área total de la comuna × 100.',limit:'El indicador describe cobertura física. Su lectura requiere considerar drenaje, recarga del acuífero y diferencias entre imágenes.',action:'Promueve el cuidado de áreas permeables y la recuperación de bordes verdes.',doc:'Informe Ejecutivo Comuna',page:16,map:'impermeable',series:[['2001',17.9],['2012',29.4],['2016',29.9],['2020',34.9],['2023',34.6],['2025',34.5]],max:40,ic:'water'},
 {id:'c-ecosistemas',name:'Ecosistemas estratégicos',topic:'Biodiversidad',kind:'Estado',value:'400,32 ha',period:'Análisis territorial · 2025',unit:'Hectáreas',description:'Reconoce espacios que sostienen la biodiversidad y la conectividad ecológica.',meaning:'El informe ejecutivo clasifica 33,49 ha de importancia alta, 295,18 ha media y 71,65 ha básica. Sus funciones incluyen hábitat, conectividad y regulación hídrica.',method:'Cruce de cobertura vegetal, conectividad y tamaño de los fragmentos. La tabla 3 del informe ejecutivo es la referencia adoptada.',limit:'Las piezas gráficas también muestran 432 ha y etiquetas de categorías diferentes. Se conserva la tabla del informe ejecutivo, sin mezclar universos ni recalcular porcentajes.',action:'Conoce y cuida humedales y corredores. Acompaña procesos comunitarios de restauración con orientación técnica.',doc:'Informe Ejecutivo Comuna',page:22,map:'ecosistemas',ic:'leaf'},
 {id:'c-fragmentacion',name:'Fragmentación de ecosistemas',topic:'Ordenamiento territorial',kind:'Presión',value:'149 cruces',period:'Infraestructura y ecosistemas · 2025',unit:'Cruces y hectáreas',description:'Explica cómo vías y construcciones interrumpen la continuidad de los ecosistemas.',meaning:'El material de resultados reporta 149 cruces, 32,6 ha ocupadas por vías y 76,8 ha por construcciones dentro del ámbito analizado.',method:'Superposición de superficies duras y vías con las áreas de importancia ambiental.',limit:'Los documentos presentan áreas base diferentes (179,18 ha en el texto y cifras gráficas con otro ámbito). Se muestran cruces y áreas reportadas sin calcular un porcentaje total nuevo.',action:'Identifica barreras en corredores y aporta observaciones al diálogo comunitario sobre conectividad.',doc:'Resultados de Indicaores',page:3,map:'fragmentacion',ic:'map'},
 {id:'c-espacio',name:'Espacio público por habitante',topic:'Espacio público',kind:'Estado',value:'23,72 m²/hab',period:'Valor reportado · 2023',unit:'Metros cuadrados por habitante',description:'Relaciona la superficie de espacio público registrada con la población residente.',meaning:'La lámina de resultados reporta 23,72 m² por habitante en 2023. El informe advierte que cantidad y acceso efectivo no son equivalentes.',method:'Área de espacio público registrada en m² / población de la comuna.',limit:'El inventario incluye componentes de la estructura ecológica. El informe pide depurarlo y diferenciar espacio público de espacio público efectivo: el valor no garantiza acceso, calidad ni uso real.',action:'Reconoce condiciones de acceso y uso de parques y zonas verdes en tu sector.',doc:'Resultados de Indicaores',page:7,map:'espacio',ic:'people',caution:true},
 {id:'c-aves',name:'Especies de aves observadas',topic:'Biodiversidad',kind:'Estado',value:'211 especies',period:'2020–2025 · seis localidades',unit:'Especies distintas',description:'Mide la riqueza de aves registrada en las localidades estudiadas.',meaning:'El seguimiento de seis localidades reporta 211 especies en 2020–2025. El acumulado histórico de la comuna es de 317 especies: son coberturas temporales distintas.',method:'Conteo de especies distintas por localidad y periodo. La suma de riquezas de localidades duplica especies compartidas.',limit:'La presencia registrada depende del esfuerzo de observación. El Excel entregado tiene otra cobertura y no reemplaza la cifra histórica del informe.',action:'Aprende a identificar aves y participa en observación respetuosa sin manipular fauna.',doc:'Informe Ejecutivo Comuna',page:38,map:'aves',ic:'bird'},
 {id:'c-flora',name:'Especies arbóreas y arbustivas',topic:'Biodiversidad',kind:'Estado',value:'63 especies',period:'Muestreo de seis localidades · 2025',unit:'Especies distintas',description:'Describe la diversidad de árboles y arbustos en los sitios muestreados.',meaning:'La lámina de resultados reporta 63 especies en seis localidades durante 2025. El registro histórico de plantas de la comuna asciende a 287 especies.',method:'Inventarios de árboles y arbustos, complementados con registros históricos. La riqueza es el número de especies, no el número de individuos.',limit:'No representa un censo de toda la comuna. Los sitios tienen condiciones y esfuerzos de muestreo distintos.',action:'Conoce las plantas del territorio y promueve restauración con especies apropiadas y asesoría técnica.',doc:'Resultados de Indicaores',page:9,map:'flora',ic:'leaf'}
];
const topics=[['Residuos sólidos','Separación, recolección y aprovechamiento.','trash'],['Calidad del aire','Material particulado y fuentes de contaminación.','sun'],['Cambio climático','Temperatura, lluvias y cobertura vegetal.','sun'],['Ruido','Fuentes de ruido y calidad del entorno.','sound'],['Cultura ambiental','Hábitos y conocimiento para cuidar el territorio.','people'],['Recurso hídrico','Fuentes, calidad y uso del agua.','water'],['Ordenamiento territorial','Ocupación, servicios y protección del suelo.','map'],['Biodiversidad','Hábitats, especies y restauración.','leaf'],['Gobernanza y justicia ambiental','Acceso a información y participación.','people'],['Bioeconomía','Negocios verdes y prácticas sostenibles.','leaf']];
const mapTopics={crecimiento:['Crecimiento urbano','crecimiento_urbano','Observa la transformación de las áreas construidas en cada corte temporal.'],impermeable:['Impermeabilización del suelo','impermeabilizacion_suelo','Las superficies impermeables limitan la infiltración del agua en el suelo.'],ecosistemas:['Ecosistemas estratégicos','ecosistemas_estrategicos','Reconoce los espacios clasificados por su importancia para la biodiversidad.'],fragmentacion:['Fragmentación de ecosistemas','fragmentacion_ecosistema_vial','Identifica la relación entre la infraestructura vial y los ecosistemas.'],espacio:['Espacio público','espacio_publico','Consulta el inventario cartográfico. La presencia en el mapa no garantiza acceso público efectivo.'],aves:['Especies de aves','especies_aves','Cartografía de la riqueza de aves por localidad. Revisa el periodo indicado dentro del mapa.'],flora:['Árboles y arbustos','especies_arboreas','Reconoce las localidades del muestreo de flora.'],ocupacion:['Ocupación del suelo','porcentaje_ocupacion','Distribución espacial de la ocupación del suelo.'],corredor:['Corredor ecológico','corredor_ecologico','Cartografía del corredor ecológico del territorio.'],interes:['Zonas de interés','zonas_interes','Áreas de interés identificadas en la entrega cartográfica.']};
function bars(items,max,unit='%'){return `<div class="chart" role="img" aria-label="${esc(items.map(([a,b])=>a+': '+nfmt(b)+' '+unit).join('; '))}">${items.map(([a,b])=>`<div class="bar-row"><span>${esc(a)}</span><div class="track"><div class="bar" style="width:${Math.min(100,b/max*100)}%"></div></div><strong>${nfmt(b)} ${unit}</strong></div>`).join('')}</div>`;}
function metric(i){const match=i.value.match(/^([\d.,]+)\s*(.*)$/),value=match?`${match[1]}<span class="unit">${esc(match[2])}</span>`:esc(i.value);return `<button class="metric" data-detail="${i.id}"><div class="metric-top">${icon(i.ic)}<span class="tag">${i.period.includes('2020')?'2020–2025':i.period.startsWith('Histórico')?'Histórico':'2025'}</span></div><div class="value">${value}</div><h3>${i.name}</h3><p>${i.period}</p></button>`;}
function topicCards(items){return `<div class="topic-grid">${items.map(([t,desc,ic])=>`<a class="topic" href="#indicadores?tema=${encodeURIComponent(t)}">${icon(ic)}<h3>${esc(t)}</h3><p>${esc(desc)}</p><span class="link">Explorar indicadores ${icon('arrow')}</span></a>`).join('')}</div>`;}
function inicioOriginal(){
 const c=territory==='comuna22';
 return head('Conoce, comprende y cuida.','Información ambiental para participar en las decisiones de tu territorio.')+`<section class="hero"><div class="hero-copy"><span class="eyebrow">${c?'Naturaleza y ciudad':'Territorio rural y comunidad'}</span><h2>${c?'Un territorio que se transforma.<br>Una comunidad que observa.':'Observar La Buitrera<br>es empezar a cuidarla.'}</h2><p>${c?'Descubre cómo se relacionan el crecimiento urbano, el agua y la biodiversidad de la Comuna 22.':'Conoce la formulación del observatorio, sus temas ambientales y las oportunidades de participación comunitaria.'}</p>${btn(c?'Explorar los mapas':'Conocer los indicadores',c?'#mapas':'#indicadores','light')}</div><div class="hero-art"><img src="assets/ave-15-0.jpg" alt="Ave fotografiada en la guía comunitaria de la Comuna 22"><span class="hero-credit">Imagen: guía comunitaria · Universidad del Valle, 2025</span></div></section>${welcomeRoute()}<div class="intro-strip">${icon('info')}<span>${c?'Resultados de estudios del proyecto 2025. Cada indicador conserva su periodo de referencia.':'La documentación corresponde a la formulación del observatorio en 2025. Las fichas definen qué medir; no constituyen una serie de mediciones cargada.'}</span></div>`+
 (c?`<div class="section-head"><div><h2>El territorio en cifras</h2><p>Una primera lectura de los resultados disponibles.</p></div><a class="link" href="#indicadores">Ver los 7 indicadores ${icon('arrow')}</a></div><div class="metric-grid">${[mainIndicators[1],mainIndicators[2],mainIndicators[5],mainIndicators[6]].map(metric).join('')}</div><div class="two-col"><section class="panel"><div class="section-head"><h2>¿Cómo ha cambiado el suelo?</h2><span class="tag">Comuna 22</span></div><p>Porcentaje de suelo impermeabilizado. Construcciones y pavimentos reducen la infiltración del agua.</p>${bars(mainIndicators[1].series,40)}<div class="source-line">Fuente: ${source('Resultado de Componente OT',3)}.</div></section><section class="panel"><div class="section-head"><h2>Lee el territorio en el mapa</h2><a class="link" href="#mapas">Explorar ${icon('arrow')}</a></div><a href="#mapas"><img class="map-preview" src="assets/ecosistemas_estrategicos_2025.jpg" alt="Vista del mapa de ecosistemas estratégicos de la Comuna 22"></a><p>Consulta los mapas originales y compara los cortes históricos disponibles.</p><div class="source-line">Fuente: Entrega SIG · Equipo OAC22 · 2025.</div></section></div>`:notice('<strong>Un punto de partida para el seguimiento ambiental.</strong><p>Consulta las 111 fichas de indicadores en diez componentes. Las cifras se incorporarán cuando existan mediciones verificadas y una fuente definida.</p>')+`<div class="two-col"><section class="panel"><h2>¿Qué se formuló?</h2><p>Un modelo para organizar información ambiental, territorial y social, interpretarla y apoyar decisiones informadas.</p><div class="step-list" style="margin-top:20px"><div class="step"><div><h3>Conocer el territorio</h3><p>Integrar conocimiento comunitario y documentación técnica.</p></div></div><div class="step"><div><h3>Comprender las dinámicas</h3><p>Relacionar presiones, estado del ambiente y respuestas.</p></div></div><div class="step"><div><h3>Participar con información</h3><p>Usar la evidencia para dialogar y priorizar acciones de cuidado.</p></div></div></div><div class="source-line">${source('Informe Ejecutivo Buitrera',7)}</div></section><section class="panel"><h2>La Buitrera en contexto</h2><a href="#mapas"><img class="map-preview" src="assets/mapa-buitrera.jpg" alt="Ubicación del corregimiento en el informe ejecutivo" style="margin-top:16px;object-fit:contain"></a><p>Un territorio estratégico en la relación entre el área urbana y los ecosistemas rurales de Cali.</p>${btn('Consultar documentos','#biblioteca')}</section></div>`)+
 `<div class="section-head"><div><h2>Explora por temas</h2><p>Encuentra una pregunta de tu vida cotidiana.</p></div></div>${topicCards(c?[['Ordenamiento territorial','Cómo cambian las construcciones y el suelo.','map'],['Biodiversidad','Las especies y los ecosistemas que compartimos.','bird'],['Espacio público','Disponibilidad, calidad y acceso a las áreas colectivas.','people']]:topics)}<div class="notice"><strong>Tu conocimiento también cuenta.</strong> Aprende a observar el territorio, consulta el material comunitario y prepara tus aportes. <a href="#participa">Participa y aprende</a>.</div>`;
}

function welcomeRoute(){return `<section class="panel welcome-route"><span class="eyebrow">Una misma ruta para conocer cada territorio</span><h2>Elige un tema y conecta la información</h2><p>Consulta el resumen, entiende sus indicadores, ubícalos en el mapa y revisa las fuentes antes de descargar.</p><div class="download-actions">${btn('Explorar paneles de '+territoryName(),'#paneles','primary')}${btn('Consultar documentos','#biblioteca')}</div><p class="small">${territory==='comuna22'?'Comuna 22 reúne resultados históricos y cartografía de la entrega.':'La Buitrera reúne fichas formuladas. Sin mediciones cargadas no significa cero ni ausencia de problemas.'}</p></section>`;}
function inicio(){return inicioOriginal();}
const panelRows=()=>territory==='comuna22'?mainIndicators:D.buitreraIndicators;
function panelTopics(){return [...new Set(panelRows().map(i=>i.topic))];}
function paneles(){const opts=panelTopics();if(!opts.includes(panelTopic))panelTopic=opts[0];return head('Conoce el territorio por temas.','Una lectura conectada: contexto, indicadores, mapa, interpretación y documentos. El territorio seleccionado se aplica a todo el panel.')+`<section class="panel"><div class="filters"><label class="field">Tema ambiental<select id="panel-topic">${opts.map(t=>`<option ${t===panelTopic?'selected':''}>${esc(t)}</option>`).join('')}</select></label><label class="field">Tipo PER<select id="panel-per"><option value="">Todos</option><option>Presión</option><option>Estado</option><option>Respuesta</option><option>Consultar ficha</option></select></label><label class="field search">Buscar en este tema<input id="panel-search" type="search" placeholder="Nombre o descripción del indicador"></label></div><div class="download-actions"><button class="btn" id="panel-reset">Limpiar búsqueda y tipo PER</button><button class="btn" id="panel-csv">Descargar indicadores seleccionados · CSV</button></div><p id="panel-status" role="status"></p></section><div id="panel-content"></div>`;}
function selectedPanelRows(){const q=norm($('#panel-search').value),per=$('#panel-per').value;return panelRows().filter(i=>i.topic===panelTopic&&(!per||i.kind===per)&&(!q||norm(i.name+' '+i.description).includes(q)));}
function drawPanel(){const rows=selectedPanelRows(),all=panelRows().filter(i=>i.topic===panelTopic),isC=territory==='comuna22',q=new URLSearchParams({tema:panelTopic,per:$('#panel-per').value,busqueda:$('#panel-search').value}),counts=['Presión','Estado','Respuesta','Consultar ficha'].map(k=>[k,all.filter(i=>i.kind===k).length]);$('#panel-status').textContent=`${territoryName()} · ${panelTopic} · ${rows.length} de ${all.length} ${isC?'indicadores documentados':'fichas formuladas'} en este tema. Los filtros se aplican al listado y al CSV.`;$('#panel-csv').disabled=!rows.length;const topicInfo=topics.find(t=>t[0]===panelTopic)?.[1]||'Comprende los resultados disponibles y sus límites antes de comparar.';
const preferred=isC?all.find(i=>i.series)||all[0]:null,mapKey=isC?preferred.map:null,mapItem=isC?D.maps.find(m=>m.name.startsWith(mapTopics[mapKey][1])&&m.name.endsWith('2025'))||D.maps.find(m=>m.name.startsWith(mapTopics[mapKey][1])):null;
const docs=D.documents.filter(d=>d.territory===territory);const preferredTitles=new Set(isC?all.map(i=>doc(i.doc)?.title).filter(Boolean):[doc('Anexo Indicadores')?.title,doc('Informe Ejecutivo')?.title]);const chosen=docs.filter(d=>preferredTitles.has(d.title));
$('#panel-content').innerHTML=`<section class="panel topic-overview"><span class="tag ${isC?'':'amber'}">${isC?'Resultados históricos documentados':'Formulación · sin serie de mediciones cargada'}</span><h2>${esc(panelTopic)}</h2><p>${esc(topicInfo)}</p>${isC?'<p>Los valores conservan el periodo y el alcance del estudio. No describen condiciones en tiempo real.</p>':'<p>Las fichas proponen qué observar y cómo medirlo. La cantidad de fichas describe el catálogo; no mide la calidad ambiental del territorio.</p>'}<div class="panel-summary-grid"><div><strong>${all.length}</strong><span>${isC?'Indicadores del tema':'Fichas formuladas del tema'}</span></div><div><strong>${isC?'Histórico':'Sin serie cargada'}</strong><span>${isC?'Consulta el periodo de cada resultado':'No sustituir valores faltantes por cero'}</span></div><div><strong>${isC?'Fuentes consultables':'Metodologías consultables'}</strong><span>Documentos originales disponibles al final</span></div></div></section><section class="panel topic-section"><h2>1. Indicadores e interpretación</h2><p>Consulta qué significa cada indicador, cómo se obtiene y qué limitaciones tiene.</p><div class="indicator-grid">${rows.map(i=>`<article class="indicator"><span class="tag">${esc(i.kind)}</span><h3>${esc(i.name)}</h3>${isC?`<div class="value">${esc(i.value)}</div><p>${esc(i.period)}</p>`:'<p class="tag amber">Formulado · sin mediciones cargadas</p>'}<p>${esc((i.description||'Consulta la definición y metodología en la ficha original.').slice(0,210))}</p><button class="btn" data-detail="${i.id}">Entender el indicador <span class="sr-only">${esc(i.name)}</span></button></article>`).join('')}</div>${rows.length?'':'<div class="empty"><h3>No hay resultados con estos filtros</h3><p>La ausencia de fichas o resultados en esta selección no demuestra ausencia de acciones o problemas ambientales. Limpia los filtros para recuperar el tema.</p></div>'}</section><div class="two-col topic-section"><section class="panel"><h2>2. Una lectura visual</h2>${isC?(preferred.series?`<h3>${esc(preferred.name)}</h3><p>Porcentaje de la superficie de Comuna 22 en los cortes disponibles. Esta gráfica de contexto conserva la serie completa aunque filtres las tarjetas.</p>${bars(preferred.series,preferred.max)}<p class="source-line">${source(preferred.doc,preferred.page)}</p>`:`<p>Las cifras del tema tienen unidades y alcances distintos; no se suman ni se comparan en una sola escala.</p>${all.map(i=>`<p><strong>${esc(i.value)}</strong> · ${esc(i.name)}<br><small>${esc(i.period)}</small></p>`).join('')}`):`<h3>Cómo se distribuyen las fichas del tema</h3><p>Conteo de fichas por tipo PER; no son mediciones ambientales. La gráfica conserva todo el tema aunque filtres las tarjetas.</p>${localBars(counts,Math.max(1,...counts.map(x=>x[1])))}<p class="source-line">${source('Anexo Indicadores')}</p>`}</section><section class="panel"><h2>3. Ubica la información</h2><img class="topic-map-preview" src="${isC?mapItem.file:'assets/mapa-buitrera.jpg'}" alt="${isC?'Lámina cartográfica original relacionada con '+esc(panelTopic):'Imagen de referencia territorial de La Buitrera del informe ejecutivo'}"><p>${isC?'La imagen conserva la leyenda de la entrega. En el visor puedes consultar otras láminas y las seis localidades documentadas de biodiversidad.':'La imagen sitúa el corregimiento. No muestra estaciones ni resultados por vereda; no se trasladan aquí las cifras de Comuna 22.'}</p>${btn(isC?'Explorar mapas relacionados':'Abrir mapa de referencia',isC?'#mapas?tema='+mapKey:'#mapas')}<p class="source-line">${isC?'Fuente: entrega SIG OAC22 · 2025.':source('Informe Ejecutivo',3)}</p></section></div><section class="panel topic-section"><h2>4. Del dato a la participación</h2>${isC?all.map(i=>`<details><summary>${esc(i.name)} · cómo leerlo y participar</summary><p><strong>Alcance:</strong> ${esc(i.limit)}</p><p><strong>Orientación para la consulta ciudadana:</strong> ${esc(i.action)}</p><p>${source(i.doc,i.page)}</p></details>`).join(''):`<p>Antes de usar una ficha, revisa su objetivo, fórmula, fuente, unidad y periodicidad. Para obtener resultados se requiere reunir y validar mediciones; la formulación por sí sola no demuestra ejecución de programas.</p><p>${source('Anexo Indicadores')}</p>`}${btn('Preparar una nota ciudadana','#participa')}</section><section class="panel topic-section"><h2>5. Documentos y descargas</h2><p>Consulta los documentos que respaldan el tema. Las descargas conservan el territorio y el alcance de la selección.</p><div class="library">${chosen.map(d=>`<article class="doc"><div><h3>${esc(d.title)}</h3><p>${esc(d.format)} · ${nfmt(d.size)} MB</p></div><a class="btn" href="${d.file}" target="_blank" rel="noopener">Consultar archivo <span class="sr-only">${esc(d.title)}</span></a></article>`).join('')}</div><div class="download-actions">${btn('Continuar con estos filtros en indicadores','#indicadores?'+q)}${btn('Abrir descarga con esta selección','#descargas?'+q)}${btn('Ver biblioteca del territorio','#biblioteca')}</div></section><section class="panel topic-section"><h2>Reportes y actualizaciones</h2><p>${isC?'Los documentos corresponden a la entrega del proyecto 2025.':'La documentación corresponde a la formulación del observatorio.'} No hay boletines mensuales ni registros instantáneos verificados cargados en este prototipo.</p></section>`;}

function indicators(){return head('Indicadores para entender.',territory==='comuna22'?'Resultados sobre las transformaciones urbanas y la biodiversidad. Consulta qué mide cada indicador, su fuente y sus límites.':'Fichas formuladas para el seguimiento ambiental. Explora qué se propone medir y consulta la metodología original.',`<button class="btn" id="export-ind">${icon('download')} Descargar CSV</button>`)+(territory==='buitrera'?notice('Las fichas son propuestas de medición. <strong>Sin serie de datos cargada</strong> no significa cero ni una condición ambiental favorable.',true):'')+`<div class="filters"><label class="field search">Buscar un indicador<input id="indicator-search" type="search" placeholder="Por ejemplo: agua, aves, suelo…"></label><label class="field">Tema<select id="indicator-topic"><option value="">Todos los temas</option>${[...new Set((territory==='comuna22'?mainIndicators:D.buitreraIndicators).map(i=>i.topic))].map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label class="field">Tipo PER<select id="indicator-kind"><option value="">Todos</option><option>Presión</option><option>Estado</option><option>Respuesta</option></select></label></div><button class="btn" id="reset-ind">Limpiar filtros</button><div id="indicator-results" aria-live="polite" aria-atomic="false"></div>`;}
function filteredIndicators(){const q=norm($('#indicator-search').value),t=$('#indicator-topic').value,k=$('#indicator-kind').value;return (territory==='comuna22'?mainIndicators:D.buitreraIndicators).filter(i=>(!q||norm(i.name+' '+i.description+' '+i.topic).includes(q))&&(!t||i.topic===t)&&(!k||i.kind===k));}
function drawIndicators(){const rows=filteredIndicators();$('#export-ind').disabled=!rows.length;const pages=Math.max(1,Math.ceil(rows.length/12));indPage=Math.min(indPage,pages);$('#indicator-results').innerHTML=`<div class="filter-summary" role="status"><span>${rows.length} indicadores encontrados${['indicator-search','indicator-topic','indicator-kind'].map(id=>$('#'+id).value).filter(Boolean).map(v=>' · '+esc(v)).join('')}</span><span>${territory==='comuna22'?'Resultados documentados':'Catálogo de fichas · formulación 2025'}</span></div><div class="indicator-grid">${rows.slice((indPage-1)*12,indPage*12).map(i=>`<article class="indicator"><div class="meta"><span class="tag ${i.caution?'amber':''}">${esc(i.kind)}</span>${esc(i.topic)}</div><h3>${esc(i.name)}</h3>${i.value?`<div class="value">${esc(i.value)}</div><div class="period">${esc(i.period)}</div>`:`<p><span class="tag amber">Sin serie cargada</span></p>`}<p>${esc(i.description?i.description.slice(0,190)+(i.description.length>190?'…':''):'Ficha técnica para el seguimiento del componente. Consulta objetivos y metodología en el documento original.')}</p><button class="btn" data-detail="${i.id}">Entender el indicador ${icon('arrow')}</button></article>`).join('')}</div>${!rows.length?'<div class="empty"><h3>No hay coincidencias con estos filtros</h3><p>'+((territory==='comuna22'&&$('#indicator-kind').value==='Respuesta')?'Comuna 22 no tiene indicadores de Respuesta con resultados cargados. Los documentos contienen recomendaciones de acción, que no equivalen a mediciones de ejecución.':'Prueba otra palabra o cambia los filtros. Las fichas de La Buitrera corresponden únicamente a ese territorio.')+'</p></div>':''}${pagination(indPage,pages,'ind')}`;}
function pagination(page,total,prefix){return total>1?`<div class="pages"><button class="btn" data-page="${prefix}" data-step="-1" ${page===1?'disabled':''}>Anterior</button><span>Página ${page} de ${total}</span><button class="btn" data-page="${prefix}" data-step="1" ${page===total?'disabled':''}>Siguiente</button></div>`:'';}
function detail(id){const isC=id.startsWith('c-'),i=(isC?mainIndicators:D.buitreraIndicators).find(i=>i.id===id);if(!i)return;let body;
 if(isC){body=`<div class="dialog-value">${esc(i.value)}</div><p>${esc(i.period)}</p><h3>¿Qué significa para la ciudadanía?</h3><p>${esc(i.meaning)}</p>${i.series?bars(i.series,i.max):''}<div class="detail-grid"><div><b>Unidad</b>${esc(i.unit)}</div><div><b>Tipo de indicador</b>${esc(i.kind)}</div></div><h3>¿Cómo se obtiene?</h3><p>${esc(i.method)}</p>${notice('<strong>Cómo leer este resultado</strong><p>'+esc(i.limit)+'</p>',true)}<h3>¿Cómo puedes participar?</h3><p>${esc(i.action)}</p><div class="source-line">Fuente: ${source(i.doc,i.page,'comuna22')}${i.id==='c-espacio'?'<br>Advertencias del inventario: '+source('Informe Ejecutivo Comuna',35,'comuna22'):''}.</div>${btn('Ver mapa relacionado','#mapas?tema='+i.map,'primary')}`;}
 else body=`<span class="tag amber">Formulado · sin serie de mediciones cargada</span><h3>¿Qué propone observar?</h3><p>${esc(i.description||'La ficha original define el objetivo y el alcance del indicador en el territorio. Consulta el documento para conocer la metodología completa.')}</p><div class="detail-grid"><div><b>Componente</b>${esc(i.topic)}</div><div><b>Modelo PER</b>${esc(i.kind)}</div><div><b>Territorio</b>Corregimiento La Buitrera</div><div><b>Referencia</b>Formulación del observatorio · 2025</div></div>${notice('Aún no hay una serie de mediciones incorporada a este prototipo. La ficha contiene las fuentes, unidades y periodicidad propuestas; no equivale a un resultado observado.',true)}<h3>Consulta la metodología completa</h3><p>La ficha original permite revisar definición, fórmula, frecuencia y condiciones de medición.</p><div class="source-line">${source('Anexo Indicadores',i.page,'buitrera')}</div>`;
 $('#detail-content').innerHTML=`<div class="dialog-head"><div><span class="eyebrow">${isC?'Comuna 22':'La Buitrera'} · ${esc(i.topic)}</span><h2 id="detail-title">${esc(i.name)}</h2></div><button class="close" aria-label="Cerrar detalle">×</button></div><div class="dialog-body">${body}</div>`;$('#detail').showModal();}
function mapas(){if(territory!=='comuna22')return (window.documentMapPanel?window.documentMapPanel(territory):'')+originalMaps();return `<div class="map-view-tabs" role="group" aria-label="Elegir vista de mapas"><button class="btn" id="view-interactive" aria-controls="view-interactive-panel" aria-pressed="true">Mapa interactivo</button><button class="btn" id="view-originals" aria-controls="view-originals-panel" aria-pressed="false">Mapas originales</button></div><div id="view-interactive-panel">${window.documentMapPanel?window.documentMapPanel(territory):'<p>El visor interactivo no está disponible en este entorno. Consulta Mapas originales.</p>'}</div><div id="view-originals-panel" hidden>${originalMaps()}</div>`;}
function selectMapView(view){if(window.history){const parts=location.hash.slice(1).split('?'),p=new URLSearchParams(parts[1]||'');p.set('vista',view==='interactivo'?'interactivo':'originales');p.set('territorio',territory);window.history.replaceState(null,'','#mapas?'+p.toString());}const interactive=view==='interactivo';$('#view-interactive-panel').hidden=!interactive;$('#view-originals-panel').hidden=interactive;$('#view-interactive').setAttribute('aria-pressed',String(interactive));$('#view-originals').setAttribute('aria-pressed',String(!interactive));window.destroyDocumentMap?.();if(interactive)window.initDocumentMap?.(territory);}
function originalMaps(){const c=territory==='comuna22';return `<div class="download-actions"><a class="btn" href="#indicadores">Consultar fichas e interpretación</a><a class="btn" href="#descargas">Abrir panel de descargas</a></div>`+head('El territorio, en sus mapas.',c?'Explora la cartografía original del proyecto y compara los años disponibles.':'Reconoce la ubicación del corregimiento en el material de formulación.')+notice(c?'Atlas de mapas originales: usa el zoom y las barras de desplazamiento para leer cada lámina y su leyenda. Los cortes son históricos; no son datos en tiempo real.':'La entrega de La Buitrera incluye una imagen de ubicación en el informe ejecutivo. No se suministró una base geográfica equivalente a la de Comuna 22.')+`<div class="atlas"><aside class="atlas-aside"><h3>${icon('map')} Selecciona el mapa</h3>${c?`<label class="field">Tema<select id="map-topic">${Object.entries(mapTopics).map(([k,v])=>`<option value="${k}">${v[0]}</option>`).join('')}</select></label><label class="field">Corte disponible<select id="map-year"></select></label>`:'<p>Perímetro urbano de Santiago de Cali y corregimiento La Buitrera.</p>'}<p>La leyenda, la escala y las fuentes se conservan dentro de la lámina.</p><a class="btn" id="map-download" download>${icon('download')} Descargar imagen</a></aside><div><section class="viewer"><div class="map-toolbar"><span id="map-title"></span><div class="map-actions"><button id="zoom-out" aria-label="Reducir mapa">−</button><button id="zoom-reset" aria-label="Ajustar mapa">100 %</button><button id="zoom-in" aria-label="Ampliar mapa">+</button></div></div><div class="map-scroll" id="map-scroll" tabindex="0" role="region" aria-label="Mapa ampliable; usa las flechas para desplazarte"><img id="map-image" alt=""></div><div class="map-caption" id="map-caption"></div></section><div class="atlas-description" id="map-description"></div></div></div>`;}
function mapYears(){const key=$('#map-topic').value,prefix=mapTopics[key][1],maps=D.maps.filter(m=>m.name.startsWith(prefix));$('#map-year').innerHTML=maps.sort((a,b)=>b.name.localeCompare(a.name)).map(m=>`<option value="${m.file}">${m.name.match(/\d{4}$/)?.[0]||'Comparación multitemporal'}</option>`).join('');drawMap();}
function drawMap(){const c=territory==='comuna22',key=c?$('#map-topic').value:'buitrera',f=c?$('#map-year').value:'assets/mapa-buitrera.jpg',title=c?mapTopics[key][0]+' · '+$('#map-year').selectedOptions[0]?.textContent:'Ubicación de La Buitrera';$('#map-image').src=f;$('#map-image').alt=title+' · cartografía del proyecto';$('#map-title').textContent=title;$('#map-download').href=f;$('#map-caption').innerHTML=c?'Fuente: Entrega SIG · Equipo OAC22 / Universidad del Valle · 2025. Revisa la leyenda original.':'Fuente: '+source('Informe Ejecutivo Buitrera',3)+'.';$('#map-description').innerHTML=`<h3>¿Qué puedes leer aquí?</h3><p>${c?mapTopics[key][2]:'La relación espacial entre el área urbana de Cali y el corregimiento. Esta imagen no es un mapa de estaciones de monitoreo.'}</p>`;zoom(0);}
function zoom(delta){mapZoom=delta?Math.max(70,Math.min(300,mapZoom+delta)):100;$('#map-image').style.width=mapZoom+'%';$('#zoom-reset').textContent=mapZoom+' %';}

function documentationPanels(){return `<section class="panel" style="margin-bottom:24px"><h2>Guía de consulta y recomendaciones</h2><details><summary>Cómo leer los paneles del observatorio</summary><p>Indicadores explica resultados y fichas; Mapas conserva las láminas originales; Panel de descargas permite reutilizar las filas disponibles; Documentación conserva los archivos fuente. El territorio seleccionado se aplica a todas estas consultas.</p><p>La propuesta de paneles del informe final de Comuna 22 se describe en las páginas PDF 180–197 (numeración interna desplazada en una página). El atlas actual no activa capas SIG ni consulta nodos de monitoreo.</p></details><details><summary>Recomendaciones del territorio seleccionado</summary>${territory==='comuna22'?`<p>Los resultados de biodiversidad proponen restauración participativa con especies nativas, caminatas y talleres de educación ambiental. Son orientaciones del estudio; no prueban que las actividades se hayan ejecutado.</p><p>Fuente: ${source('Resultados de Indicaores',2)}; también páginas 6 y 10 del mismo documento.</p>`:`<p>La formulación propone seguimiento ambiental y participación comunitaria. Consulta las fichas para conocer objetivos, fuentes, unidades y periodicidad antes de implementar acciones.</p><p>Fuente: ${source('Anexo Indicadores',99)}.</p>`}</details><details><summary>Boletines, estaciones y accesibilidad de los documentos</summary><p>No se cargaron boletines periódicos de estaciones, registros instantáneos ni máximos y mínimos. Los informes se ofrecen con sus fechas originales, sin presentarlos como boletines de monitoreo actual.</p><p>Los archivos originales pueden contener imágenes, tablas sin etiquetas o PDF sin estructura accesible. Las fichas y tablas HTML ofrecen una alternativa textual parcial; no sustituyen todo el contenido documental.</p></details></section>`;}

function docNav(){return `<nav class="doc-section-nav" aria-label="Secciones de documentación">${[['todos','Todos'],['estudios','Estudios'],['recomendaciones','Recomendaciones'],['guias','Guías'],['datos','Datos y anexos']].map(([k,n])=>`<a class="btn ${docSection===k?'primary':''}" href="#biblioteca?seccion=${k}" ${docSection===k?'aria-current="page"':''}>${n}</a>`).join('')}</nav>`;}
function docCategory(d){if(/guia|cartilla|como formular/.test(norm(d.title)))return 'guias';if(d.format!=='PDF')return 'datos';return 'estudios';}
function biblioteca(){return head('Documentación del territorio.','Estudios, orientaciones, guías y datos de '+territoryName()+'. Consulta sus fuentes y periodos antes de reutilizar la información.')+docNav()+(docSection==='recomendaciones'?documentationPanels():`<p class="notice">${docSection==='todos'?'Todos los archivos del territorio seleccionado.':docSection==='estudios'?'Informes y documentos de resultados o formulación.':docSection==='guias'?'Materiales pedagógicos y guías de consulta disponibles.':'Archivos tabulares, geográficos e imágenes de la entrega.'}</p><div class="filters"><label class="field search">Buscar en esta sección<input id="doc-search" type="search" placeholder="Informe, indicadores, aves, cartografía…"></label><label class="field">Formato<select id="doc-format"><option value="">Todos los formatos</option><option>PDF</option><option>XLSX</option><option>JPG</option><option>ZIP / GDB</option></select></label></div><button class="btn" id="reset-doc">Limpiar filtros</button><div id="doc-results" aria-live="polite"></div>`);}
function drawDocs(){const q=norm($('#doc-search').value),fmt=$('#doc-format').value,rows=D.documents.filter(d=>d.territory===territory&&(docSection==='todos'||docCategory(d)===docSection)&&(!q||norm(d.title).includes(q))&&(!fmt||d.format===fmt));$('#doc-results').innerHTML=`<div class="filter-summary" role="status">${rows.length} documentos y conjuntos de datos · ${territoryName()}</div><div class="library">${rows.map(d=>`<article class="doc"><div class="doc-icon">${icon('file')}</div><div><h3>${esc(d.title)}</h3><p>${esc(d.format)} · ${d.size<.1?'Menos de 0,1':nfmt(d.size)} MB · Entrega del proyecto 2025${norm(d.title).includes('proyeccion')?' · Escenario referencial de sostenibilidad':''}</p></div><div class="doc-actions">${['PDF','JPG'].includes(d.format)?`<a class="btn" target="_blank" rel="noopener" href="${d.file}">Abrir ${icon('arrow')}</a>`:''}<a class="btn" href="${d.file}" download aria-label="Descargar ${esc(d.title)}">${icon('download')} Descargar</a></div></article>`).join('')}</div>${!rows.length?'<div class="empty">No hay documentos con esos filtros.</div>':''}<div class="source-line">Los informes completos pueden tardar en abrir por su tamaño. El informe final de biodiversidad y el informe final de Comuna 22 son copias idénticas en la entrega: se ofrece una sola descarga.</div>`;}
function biodiversidad(){if(territory==='buitrera')return head('La vida que sostiene el territorio.','La formulación propone observar coberturas, conectividad, aves, anfibios y especies exóticas invasoras.')+notice('Los inventarios de aves y flora entregados corresponden a la Comuna 22. No se atribuyen esas especies ni sus cifras a La Buitrera.')+topicCards([['Biodiversidad','Conoce las fichas para el seguimiento de especies, coberturas y restauración.','bird']])+`<div class="panel" style="margin-top:22px"><h2>Conocimiento comunitario y conservación</h2><p>La formulación plantea campañas educativas, monitoreo comunitario de aves y anfibios y seguimiento a las áreas de importancia hídrica.</p><div class="source-line">Fuente: ${source('Anexo Indicadores',99)}.</div>${btn('Leer el informe ejecutivo','#biblioteca')}</div>`;
 return head('Conoce la vida que te rodea.','Humedales y corredores sostienen una riqueza de aves, árboles y arbustos que merece ser conocida y cuidada.')+`<div class="tabs" role="tablist" aria-label="Consultar biodiversidad">${[['resumen','Panorama de biodiversidad'],['aves','Registros de aves'],['flora','Plantas de importancia']].map(([k,v])=>`<button role="tab" aria-selected="${bioTab===k}" class="${bioTab===k?'active':''}" data-biotab="${k}">${v}</button>`).join('')}</div><div id="bio-content"></div>`;}
function drawBio(){if(territory!=='comuna22')return;const root=$('#bio-content');if(bioTab==='resumen'){root.innerHTML=`<div class="metric-grid">${[mainIndicators[5],mainIndicators[6],{...mainIndicators[5],value:'317 especies',name:'Acumulado histórico de aves',period:'Histórico · informe 2025'},{...mainIndicators[6],value:'287 especies',name:'Acumulado histórico de plantas',period:'Histórico · informe 2025'}].map(metric).join('')}</div>${notice('El histórico y el muestreo de seis localidades tienen coberturas distintas. Las especies compartidas entre sitios se cuentan una sola vez en la riqueza total.')}<div class="two-col"><section class="panel"><h2>Riqueza de aves por localidad</h2><p>Especies registradas en 2020–2025.</p>${localBars([['Lago de las Garzas',173],['La Babilla y Zanjón del Burro',137],['Cañasgordas',73],['Bosque Urbano Umbría',62],['El Retiro',60],['Panamericano',56]],180)}<div class="source-line">${source('Resultados de Indicaores',5)}</div></section><section class="panel"><h2>Riqueza de plantas por localidad</h2><p>Especies arbóreas y arbustivas · muestreo 2025.</p>${localBars([['Lago de las Garzas',33],['La Babilla',22],['Cañasgordas',22],['El Retiro',18],['Panamericano',14],['Bosque Urbano Umbría',11]],35)}<div class="source-line">${source('Informe Ejecutivo Comuna',44)}</div></section></div><section class="bio-guide" style="margin-top:22px"><img src="assets/guia-aves.jpg" alt="Portada de la guía comunitaria de aves, árboles y arbustos"><div><span class="eyebrow">Aprender para conservar</span><h2>Una guía para mirar con otros ojos.</h2><p>Material comunitario para reconocer aves, árboles y arbustos de la Comuna 22.</p><a class="btn primary" href="${doc('Guía').file}" target="_blank" rel="noopener">Abrir la guía ${icon('book')}</a></div></section>`;}
 else{root.innerHTML=notice(bioTab==='aves'?`El anexo Excel contiene ${D.birds.length} filas y ${new Set(D.birds.map(b=>b.species)).size} nombres de especie distintos. No incluye fecha por registro. Su cobertura difiere del informe histórico de 211 especies en seis localidades.`:'Selección transcrita de la hoja “Especies de importancia” del anexo de flora. Las funciones se presentan como aparecen en la fuente; no son instrucciones de plantación.')+`<div class="filters"><label class="field search">Buscar ${bioTab==='aves'?'especie, familia o localidad':'nombre común, científico o función'}<input id="bio-search" type="search" placeholder="Escribe para filtrar…"></label>${bioTab==='aves'?`<label class="field">Localidad<select id="bio-site"><option value="">Todas</option>${[...new Set(D.birds.map(b=>b.site))].sort().map(s=>`<option>${esc(s)}</option>`).join('')}</select></label>`:''}<button class="btn" id="export-bio">${icon('download')} Descargar CSV</button></div><div id="bio-results"></div>`;drawBioTable();}}
function localBars(rows,max){return `<div class="chart">${rows.map(([n,v])=>`<div style="font-size:12px"><div style="display:flex;justify-content:space-between;gap:10px;margin-bottom:6px"><span>${n}</span><strong>${v}</strong></div><div class="track"><div class="bar" style="width:${v/max*100}%"></div></div></div>`).join('')}</div>`;}
function bioRows(){const q=norm($('#bio-search').value),site=bioTab==='aves'?$('#bio-site')?.value:'';return (bioTab==='aves'?D.birds:D.plants).filter(r=>(!q||norm(Object.values(r).join(' ')).includes(q))&&(!site||r.site===site));}
function drawBioTable(){const rows=bioRows(),pages=Math.max(1,Math.ceil(rows.length/20));bioPage=Math.min(bioPage,pages);$('#bio-results').innerHTML=`<div class="filter-summary" role="status">${rows.length} registros encontrados</div><div class="table-wrap"><table><thead><tr>${(bioTab==='aves'?['Especie','Familia','Localidad','UICN en el anexo','Migración','Conteo']:['Nombre común','Nombre científico','Familia','Funciones registradas']).map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${rows.slice((bioPage-1)*20,bioPage*20).map(r=>`<tr>${(bioTab==='aves'?[`<em>${esc(r.species)}</em>`,esc(r.family),esc(r.site),esc(r.iucn),esc(r.migration),esc(r.count)]:[esc(r.common),`<em>${esc(r.species)}</em>`,esc(r.family),esc(r.function)]).map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="empty">No hay registros con esos filtros.</div>':''}${pagination(bioPage,pages,'bio')}<div class="source-line">Fuente: ${source(bioTab==='aves'?'Anexo 13':'Anexo 12')} · ${bioTab==='aves'?'Hoja1. LC: preocupación menor; NT: casi amenazada; NE: no evaluada. Son categorías transcritas del archivo, sin actualización externa.':'Hoja “Especies de importancia”.'}</div>`;}
function readNotes(){try{const n=JSON.parse(localStorage.getItem('observatorio-notas-ciudadanas')||'[]');return Array.isArray(n)?n:[];}catch{return [];}}
function participa(){return head('Participa desde el conocimiento.','Observar, comprender y dialogar son formas de contribuir al cuidado del territorio.')+`<div class="two-col"><section class="panel"><h2>Una ruta para aportar</h2><div class="step-list" style="margin-top:24px"><div class="step"><div><h3>Infórmate con las fuentes</h3><p>Lee la ficha del indicador, el periodo y los límites de la información antes de comparar resultados.</p></div></div><div class="step"><div><h3>Observa con cuidado</h3><p>Anota fecha, lugar y descripción de lo que observaste. Distingue lo que viste de tu interpretación. Evita alterar hábitats o manipular fauna.</p></div></div><div class="step"><div><h3>Construye un aporte claro</h3><p>Relaciona tu observación con un tema del observatorio y con las preguntas de tu comunidad.</p></div></div><div class="step"><div><h3>Dialoga en comunidad</h3><p>Comparte tus hallazgos en espacios comunitarios y con la institucionalidad competente. Conserva la fuente y el contexto de tus observaciones.</p></div></div></div><div class="source-line">Basado en ${source('Informe Ejecutivo',territory==='buitrera'?12:62)}.</div></section><section class="panel"><h2>Mi cuaderno de observación</h2><p>Prepara una nota para una reunión o recorrido. Se guarda únicamente en este navegador; puedes descargarla.</p><form id="note-form" class="noteform" style="margin-top:20px"><label class="field">Tema<select name="topic" required>${(territory==='buitrera'?topics.map(x=>x[0]):['Ordenamiento territorial','Biodiversidad','Espacio público']).map(t=>`<option>${t}</option>`).join('')}</select></label><label class="field">Fecha de la observación<input type="date" name="date" required></label><label class="field">Lugar o sector<input name="place" maxlength="160" required placeholder="Nombre del lugar, sin datos personales"></label><label class="field">¿Qué observaste?<textarea name="description" maxlength="2500" required placeholder="Describe lo observado y la pregunta que quieres compartir."></textarea></label><button class="btn primary" type="submit">Guardar nota en mi navegador</button><div class="form-message" id="note-message" role="status"></div></form><p class="small">Este cuaderno no envía reportes, denuncias ni solicitudes a una entidad. No genera radicados.</p></section></div><div class="section-head"><h2>Mis notas de ${territoryName()}</h2><button class="btn" id="export-notes">${icon('download')} Descargar mis notas</button></div><div id="notes-list" class="notes-list"></div><div class="section-head"><h2>Conceptos para conversar</h2></div>${glossary()}${territory==='buitrera'?`<div class="notice">Material para ampliar: ${source('Cartilla')||source('Como formular')}.</div>`:`<div class="notice">Aprende a reconocer especies con ${source('Guía')}.</div>`}`;}
function drawNotes(){const rows=readNotes().filter(n=>n.territory===territory);$('#notes-list').innerHTML=rows.length?rows.map(n=>`<article class="note-item"><span class="tag">${esc(n.topic)}</span><h3 style="margin-top:8px">${esc(n.place)}</h3><small>${esc(n.date)} · Nota personal</small><p>${esc(n.description)}</p><button class="btn" data-delete-note="${esc(n.id)}">${icon('trash')} Eliminar nota</button></article>`).join(''):'<div class="empty">Aún no has guardado notas para este territorio.</div>';}
function glossary(){return `<dl class="glossary">${[['Presión','Actividades y procesos que pueden afectar el ambiente, como la urbanización o la generación de residuos.'],['Estado','Condiciones observadas del ambiente, como la riqueza de especies o la calidad del agua.'],['Respuesta','Acciones de la comunidad y las instituciones para atender las presiones o mejorar las condiciones.'],['Riqueza de especies','Número de especies distintas registradas. Es diferente de la abundancia, que cuenta individuos.'],['Conectividad ecológica','Relación entre espacios que permite el movimiento de especies y los procesos naturales.'],['Serie histórica','Mediciones de un indicador en diferentes fechas, realizadas con un alcance y un método comparables.']].map(([t,d])=>`<div><dt>${t}</dt><dd>${d}</dd></div>`).join('')}</dl>`;}
function aboutOriginal(){return `<div class="two-col"><section class="panel"><h2>Comuna 22</h2><p>Los documentos consolidan resultados de ordenamiento territorial, espacio público y biodiversidad, con trabajo técnico y participativo del proyecto 2025.</p><div class="source-line">${source('Informe Ejecutivo Comuna',6,'comuna22')}</div></section><section class="panel"><h2>Corregimiento La Buitrera</h2><p>La entrega formula un modelo conceptual, tecnológico y administrativo, acompañado de fichas de indicadores. La formulación define las bases para una implementación posterior.</p><div class="source-line">${source('Informe Ejecutivo Buitrera',7,'buitrera')}</div></section></div><div class="section-head"><h2>Cómo se presenta la información</h2></div><section class="panel"><div class="step-list"><div class="step"><div><h3>Fuente y periodo visibles</h3><p>Los resultados conservan la fecha y el ámbito del estudio. La fecha de preparación de este prototipo no convierte un dato histórico en actual.</p></div></div><div class="step"><div><h3>Resultados y formulación diferenciados</h3><p>La ausencia de una medición aparece como “sin serie cargada”. No se sustituye por cero, un semáforo o una cifra de ejemplo.</p></div></div><div class="step"><div><h3>Documentos consultables y descargables</h3><p>La biblioteca incluye informes y anexos originales. Los mapas provienen de la entrega SIG y conservan sus leyendas.</p></div></div><div class="step"><div><h3>Alcance del prototipo</h3><p>Consulta ciudadana sin registro. El contenido procede de los archivos compartidos. No hay conexión operativa a CEMUA o IDESC ni sensores en tiempo real; no se reciben trámites ni reportes institucionales.</p></div></div></div></section><div class="section-head"><h2>Presión, Estado y Respuesta (PER)</h2></div>${glossary()}<p class="small muted">Documentación base: DAGMA y Universidad del Valle · Convenio Interadministrativo No. 4133.010.27.1.041-2025. Preparación de la versión ciudadana: 20 de octubre de 2026.</p>`;}

function descargas(){return head('Consulta y descarga los datos.','Combina filtros, revisa los resultados y elige CSV o JSON. La descarga incluye todas las filas filtradas, aunque la vista previa muestre solo las primeras veinte.')+notice('Este panel usa exclusivamente la entrega documental. Los registros de aves no tienen fecha individual; las fichas de La Buitrera no tienen mediciones. No hay estaciones conectadas ni datos en tiempo real.')+`<section class="panel"><div class="filters"><label class="field">Conjunto de datos<select id="dl-set"><option value="indicadores">Indicadores y fichas</option>${territory==='comuna22'?'<option value="series">Serie de suelo · cortes históricos</option><option value="aves">Registros de aves del anexo</option><option value="flora">Plantas de importancia</option>':''}</select></label><label class="field search">Palabra clave<input id="dl-search" type="search" placeholder="Nombre, descripción o especie"></label><label class="field">Componente<select id="dl-topic"></select></label><label class="field">Tipo PER<select id="dl-kind"><option value="">Todos</option><option>Presión</option><option>Estado</option><option>Respuesta</option><option>Consultar ficha</option></select></label><label class="field">Localidad del registro<select id="dl-site"></select></label><label class="field">Año inicial<input id="dl-from" type="number" min="1900" max="2100" placeholder="2001" aria-describedby="dl-period-help"></label><label class="field">Año final<input id="dl-to" type="number" min="1900" max="2100" placeholder="2025" aria-describedby="dl-period-help"></label></div><p id="dl-period-help"></p><button class="btn" id="reset-dl">Limpiar filtros</button></section><section class="panel" style="margin-top:20px"><div id="dl-results" aria-live="polite"></div><div class="download-actions"><button class="btn primary" id="dl-csv">Descargar CSV</button><button class="btn" id="dl-json">Descargar JSON con contexto</button><a class="btn" href="#biblioteca">Consultar archivos originales</a></div><p id="dl-status" role="status"></p></section>`;}
function setupDownload(){const set=$('#dl-set').value,inds=territory==='comuna22'?mainIndicators:D.buitreraIndicators;$('#dl-topic').innerHTML='<option value="">Todos los componentes</option>'+[...new Set(inds.map(i=>i.topic))].map(t=>`<option>${esc(t)}</option>`).join('');$('#dl-site').innerHTML='<option value="">Todas las localidades</option>'+[...new Set(D.birds.map(r=>r.site))].sort().map(t=>`<option>${esc(t)}</option>`).join('');for(const id of ['dl-topic','dl-kind']){$('#'+id).disabled=!['indicadores','series'].includes(set);$('#'+id).value='';}$('#dl-site').disabled=set!=='aves';$('#dl-site').value='';for(const id of ['dl-from','dl-to']){$('#'+id).disabled=set!=='series';$('#'+id).value='';}$('#dl-period-help').textContent=set==='series'?'El rango selecciona cortes históricos disponibles, no una serie diaria. Los años sin corte no se interpolan.':set==='aves'?'El anexo de aves no contiene fechas por registro: el filtro temporal no aplica.':set==='flora'?'La selección de flora no tiene una serie temporal: el filtro por año no aplica.':'Los periodos y estados se conservan como aparecen en cada ficha. Para filtrar años, selecciona la serie de suelo de Comuna 22.';drawDownload();}
function downloadRows(){const set=$('#dl-set').value,q=norm($('#dl-search').value),topic=$('#dl-topic').value,kind=$('#dl-kind').value,site=$('#dl-site').value;let rows=[];if(set==='indicadores')rows=(territory==='comuna22'?mainIndicators:D.buitreraIndicators).filter(i=>(!topic||i.topic===topic)&&(!kind||i.kind===kind)).map(i=>({Territorio:territoryName(),Indicador:i.name,Componente:i.topic,PER:i.kind,Valor:i.value||'',Periodo:i.period||i.status,Fuente:i.doc||'Anexo Indicadores Buitrera',PaginaPDF:i.page}));if(set==='series'){const lo=Number($('#dl-from').value||0),hi=Number($('#dl-to').value||9999);rows=mainIndicators.filter(i=>i.series&&(!topic||i.topic===topic)&&(!kind||i.kind===kind)).flatMap(i=>i.series.filter(([year])=>Number(year)>=lo&&Number(year)<=hi).map(([year,value])=>({Territorio:territoryName(),Indicador:i.name,Componente:i.topic,PER:i.kind,Anio:Number(year),Valor:value,Unidad:'Porcentaje',Fuente:i.doc,PaginaPDF:i.page})));}if(set==='aves')rows=D.birds.filter(r=>!site||r.site===site).map(r=>({Territorio:territoryName(),...r,Fuente:'Anexo 13 · Hoja1',Fecha:'No disponible por registro'}));if(set==='flora')rows=D.plants.map(r=>({Territorio:territoryName(),...r,Fuente:'Anexo 12 · Especies de importancia'}));return rows.filter(r=>!q||norm(Object.values(r).join(' ')).includes(q));}
function drawDownload(){const invalid=$('#dl-set').value==='series'&&$('#dl-from').value&&$('#dl-to').value&&Number($('#dl-from').value)>Number($('#dl-to').value),rows=invalid?[]:downloadRows(),headers=Object.keys(rows[0]||{});$('#dl-csv').disabled=$('#dl-json').disabled=!rows.length;$('#dl-results').innerHTML=`<h2>Vista previa · ${rows.length} filas</h2><p>${invalid?'El año inicial debe ser menor o igual al año final.':rows.length?'Se muestran hasta 20 filas; la descarga contiene todos los resultados.':'No hay resultados con estos filtros. Limpia los filtros o selecciona otro conjunto.'}</p>${rows.length?`<div class="table-wrap" tabindex="0" role="region" aria-label="Vista previa de la descarga; desplázate para consultar columnas"><table><caption>${esc($('#dl-set').selectedOptions[0].textContent)} · ${territoryName()}</caption><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,20).map(r=>'<tr>'+headers.map(h=>`<td>${esc(r[h])}</td>`).join('')+'</tr>').join('')}</tbody></table></div>`:''}`;$('#dl-status').textContent='';}
function exportDownload(format){const rows=downloadRows();if($('#dl-csv').disabled||!rows.length)return;const name='Observatorio_'+territory+'_'+$('#dl-set').value;if(format==='csv')csv(name+'.csv',Object.keys(rows[0]),rows.map(r=>Object.values(r)));else download(name+'.json',JSON.stringify({territorio:territoryName(),conjunto:$('#dl-set').value,filtros:{busqueda:$('#dl-search').value,componente:$('#dl-topic').value,PER:$('#dl-kind').value,localidad:$('#dl-site').value,desde:$('#dl-from').value,hasta:$('#dl-to').value},alcance:'Datos documentales históricos o fichas formuladas. Sin monitoreo en tiempo real; ausencia de valores no significa cero.',total:rows.length,registros:rows},null,2),'application/json');$('#dl-status').textContent='Se preparó la descarga de '+rows.length+' filas en '+format.toUpperCase()+'.';}


const exploreRoutes=['paneles','indicadores','mapas','biodiversidad','descargas'];
function navigationMenu(){const link=([k,n,ic])=>`<a href="#${k}" class="${route===k?'active':''}" ${route===k?'aria-current="page"':''}>${icon(ic)}${n}</a>`;return link(nav.find(n=>n[0]==='inicio'))+`<details class="nav-group" ${exploreRoutes.includes(route)?'open':''}><summary>${icon('map')} Explora tu territorio</summary><div class="nav-subgroup">${nav.filter(n=>exploreRoutes.includes(n[0])).map(link).join('')}</div></details>`+nav.filter(n=>!exploreRoutes.includes(n[0])&&n[0]!=='inicio').map(link).join('');}
function navigationContext(params){const topic=params.get('tema'),valid=panelTopics().includes(topic),back='#paneles'+(valid?'?tema='+encodeURIComponent(topic):'');return `<div class="route-context"><nav aria-label="Ruta de navegación"><a href="#inicio">Inicio</a><span aria-hidden="true"> / </span><span>${territoryName()}</span>${exploreRoutes.includes(route)?'<span aria-hidden="true"> / </span><a href="#paneles">Explora tu territorio</a>':''}<span aria-hidden="true"> / </span><strong aria-current="page">${esc(nav.find(n=>n[0]===route)[1])}</strong></nav>${exploreRoutes.includes(route)&&route!=='paneles'?`<a class="btn" href="${back}">Volver ${valid?'al tema '+esc(topic):'a los paneles por tema'}</a>`:''}</div>`;}
function acerca(){return head('Acerca del observatorio.','Conoce el propósito, los componentes y el respaldo documental del territorio seleccionado.')+`<section class="panel"><h2>${territoryName()} · información disponible</h2><p>${territory==='comuna22'?'El observatorio organiza resultados históricos sobre ordenamiento territorial, espacio público y biodiversidad, con sus documentos y cartografía.':'La formulación organiza diez componentes y 111 fichas para orientar el seguimiento ambiental. Las fichas aún no tienen series de mediciones cargadas en el prototipo.'}</p><div class="download-actions">${btn('Explorar sus componentes','#paneles')}${btn('Consultar documentación','#biblioteca')}</div></section><div class="two-col topic-section"><section class="panel"><h2>Hitos documentados y alcance temporal</h2><ol><li><strong>Proyecto 2025:</strong> ${territory==='comuna22'?'consolidación de resultados y propuesta de reorganización de la información.':'formulación del observatorio y de las fichas de indicadores.'}</li><li><strong>Prototipo de consulta ciudadana:</strong> adaptación de los materiales entregados para facilitar su consulta. La preparación de esta interfaz no actualiza las fechas de los estudios.</li></ol><p>Esta lista no constituye la historia institucional completa. Otros hitos requieren fuentes verificadas.</p><p class="source-line">${source('Informe Ejecutivo')}</p></section><section class="panel"><h2>Actores y canales de consulta</h2><p>La documentación entregada identifica al DAGMA y la Universidad del Valle en el marco del convenio del proyecto. Sus roles y los actores comunitarios se describen en los informes propios de cada territorio.</p><p>No se ha validado un directorio vigente de contactos para esta interfaz. Consulta los canales institucionales en los documentos y verifica su vigencia antes de enviar solicitudes.</p><p>El cuaderno ciudadano guarda notas personales; no radica solicitudes ni envía mensajes a las entidades.</p></section></div>`+aboutOriginal();}
function reportes(){return head('Reportes y boletines.','Disponibilidad de publicaciones para '+territoryName()+'.')+notice('<strong>Sin boletines periódicos cargados.</strong><p>Los archivos entregados incluyen informes de resultados o formulación. No se han incorporado publicaciones mensuales, lecturas instantáneas ni máximos y mínimos de estaciones verificadas.</p>',true)+`<section class="panel"><h2>Qué puedes consultar ahora</h2><p>${territory==='comuna22'?'Informes y resultados históricos del proyecto 2025, junto con los indicadores y la cartografía.':'Informe de formulación, resumen ejecutivo y fichas de indicadores sin serie de mediciones cargada.'}</p><div class="download-actions">${btn('Consultar informes','#biblioteca?seccion=estudios')}${btn('Explorar temas','#paneles')}</div></section>`;}

function csv(name,headers,rows){const cell=v=>'"'+String(/^[=+@\-\t\r]/.test(String(v??''))?"'"+v:(v??'')).replace(/"/g,'""')+'"';download(name,'\ufeff'+[headers,...rows].map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1500);}
function render(){window.destroyDocumentMap?.();if('speechSynthesis' in window)window.speechSynthesis.cancel();const hash=location.hash.slice(1)||'inicio',parts=hash.split('?');route=nav.some(n=>n[0]===parts[0])?parts[0]:'inicio';const params=new URLSearchParams(parts[1]||'');if(['comuna22','buitrera'].includes(params.get('territorio')))territory=params.get('territorio');$('#territory').value=territory;docSection=['todos','estudios','recomendaciones','guias','datos'].includes(params.get('seccion'))?params.get('seccion'):'todos';if(route==='paneles'&&panelTopics().includes(params.get('tema')))panelTopic=params.get('tema');$('#breadcrumb').textContent='/ '+nav.find(n=>n[0]===route)[1];$('#navigation').innerHTML=navigationMenu();$('#contenido').innerHTML=navigationContext(params)+({inicio,paneles,reportes,indicadores:indicators,mapas,descargas,biblioteca,biodiversidad,participa,acerca}[route])();if(route==='paneles')drawPanel();if(route==='indicadores'){indPage=1;const topic=params.get('tema');if([...$('#indicator-topic').options].some(o=>o.value===topic))$('#indicator-topic').value=topic;$('#indicator-kind').value=params.get('per')||'';$('#indicator-search').value=params.get('busqueda')||'';drawIndicators();}if(route==='mapas'){if(territory==='comuna22'){if(mapTopics[params.get('tema')])$('#map-topic').value=params.get('tema');mapYears();}else drawMap();if(territory==='comuna22')selectMapView(params.get('vista')==='originales'||(!params.has('vista')&&params.has('tema'))?'originales':'interactivo');}if(route==='descargas'){setupDownload();const topic=params.get('tema');if([...$('#dl-topic').options].some(o=>o.value===topic))$('#dl-topic').value=topic;$('#dl-kind').value=params.get('per')||'';$('#dl-search').value=params.get('busqueda')||'';drawDownload();}if(route==='biblioteca'&&docSection!=='recomendaciones')drawDocs();if(route==='biodiversidad')drawBio();if(route==='participa')drawNotes();document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');window.scrollTo(0,0);$('#contenido').focus?.({preventScroll:true});document.title=nav.find(n=>n[0]===route)[1]+' · Observatorio Ambiental';if(window.history){params.set('territorio',territory);window.history.replaceState(null,'','#'+route+'?'+params.toString());}window.decorateNavigation?.();}
$('#brand-icon').innerHTML=icon('leaf');$('#pin-icon').innerHTML=icon('pin');$('#menu-toggle').innerHTML=icon('menu');
$('#territory').addEventListener('change',e=>{territory=e.target.value;bioPage=1;const parts=location.hash.slice(1).split('?'),p=new URLSearchParams(parts[1]||'');p.set('territorio',territory);location.hash='#'+(parts[0]||'inicio')+'?'+p.toString();});
$('#menu-toggle').addEventListener('click',()=>{$('#menu-toggle').setAttribute('aria-expanded',String(document.body.classList.toggle('menu-open')));});$('#menu-shade').addEventListener('click',()=>{document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');});
window.addEventListener('hashchange',()=>{if($('#detail').open)$('#detail').close();render();});
document.addEventListener('input',e=>{if(e.target.id==='indicator-search'){indPage=1;drawIndicators();}if(e.target.id==='doc-search')drawDocs();if(e.target.id==='bio-search'){bioPage=1;drawBioTable();}});
document.addEventListener('change',e=>{if(['indicator-topic','indicator-kind'].includes(e.target.id)){indPage=1;drawIndicators();}if(e.target.id==='doc-format')drawDocs();if(e.target.id==='bio-site'){bioPage=1;drawBioTable();}if(e.target.id==='map-topic')mapYears();if(e.target.id==='map-year')drawMap();});
document.addEventListener('click',e=>{const detailButton=e.target.closest('[data-detail]');if(detailButton)detail(detailButton.dataset.detail);if(e.target.closest('.close'))$('#detail').close();const tab=e.target.closest('[data-biotab]');if(tab){bioTab=tab.dataset.biotab;bioPage=1;$('#contenido').innerHTML=biodiversidad();drawBio();}const page=e.target.closest('[data-page]');if(page){if(page.dataset.page==='ind'){indPage+=Number(page.dataset.step);drawIndicators();$('#indicator-results').scrollIntoView({block:'start'});}else{bioPage+=Number(page.dataset.step);drawBioTable();$('#bio-results').scrollIntoView({block:'start'});}}if(e.target.closest('#zoom-in'))zoom(25);if(e.target.closest('#zoom-out'))zoom(-25);if(e.target.closest('#zoom-reset'))zoom(0);if(e.target.closest('#export-ind')){const rows=filteredIndicators();csv('Indicadores_'+territory+'.csv',['Territorio','Indicador','Tema','Tipo','Valor reportado','Periodo / estado','Documento','Página PDF'],rows.map(i=>[territoryName(),i.name,i.topic,i.kind,i.value||'',i.period||i.status,i.doc||'1.2 Anexo Indicadores Buitrera',i.page]));}if(e.target.closest('#export-bio')){const r=bioRows();csv('Biodiversidad_'+bioTab+'.csv',bioTab==='aves'?['Localidad','Orden','Familia','Especie','UICN en fuente','Migración','Conteo']:['Nombre común','Especie','Familia','Funciones'],r.map(x=>Object.values(x)));}if(e.target.closest('#export-notes')){const rows=readNotes().filter(n=>n.territory===territory);download('Mis_notas_ambientales.json',JSON.stringify({territory:territoryName(),scope:'Notas personales. No enviadas a una entidad.',notes:rows},null,2),'application/json');}const del=e.target.closest('[data-delete-note]');if(del){try{localStorage.setItem('observatorio-notas-ciudadanas',JSON.stringify(readNotes().filter(n=>n.id!==del.dataset.deleteNote)));drawNotes();}catch{alert('No fue posible actualizar el almacenamiento del navegador.');}}});
document.addEventListener('submit',e=>{if(e.target.id!=='note-form')return;e.preventDefault();const f=new FormData(e.target),place=String(f.get('place')).trim(),description=String(f.get('description')).trim();if(!place||!description){$('#note-message').textContent='Completa el lugar y la descripción de tu observación.';return;}const n={id:Date.now().toString(36)+Math.random().toString(36).slice(2,8),territory,topic:f.get('topic'),date:f.get('date'),place,description};try{localStorage.setItem('observatorio-notas-ciudadanas',JSON.stringify([...readNotes(),n]));e.target.reset();$('#note-message').textContent='Nota guardada únicamente en este navegador.';drawNotes();}catch{$('#note-message').textContent='Este navegador no permite guardar la nota. Copia el texto antes de cerrar.';}});
document.addEventListener('input',e=>{if(['dl-search','dl-from','dl-to'].includes(e.target.id))drawDownload();});
document.addEventListener('change',e=>{if(e.target.id==='dl-set')setupDownload();if(['dl-topic','dl-kind','dl-site'].includes(e.target.id))drawDownload();});
document.addEventListener('click',e=>{if(e.target.closest('#reset-ind')){for(const id of ['indicator-search','indicator-topic','indicator-kind'])$('#'+id).value='';indPage=1;drawIndicators();}if(e.target.closest('#reset-doc')){$('#doc-search').value='';$('#doc-format').value='';drawDocs();}if(e.target.closest('#reset-dl')){$('#dl-search').value='';setupDownload();}if(e.target.closest('#dl-csv'))exportDownload('csv');if(e.target.closest('#dl-json'))exportDownload('json');});

document.addEventListener('change',e=>{if(e.target.id==='panel-topic'){panelTopic=e.target.value;location.hash='#paneles?tema='+encodeURIComponent(panelTopic);}if(e.target.id==='panel-per')drawPanel();});
document.addEventListener('input',e=>{if(e.target.id==='panel-search')drawPanel();});
document.addEventListener('click',e=>{if(e.target.closest('#panel-reset')){$('#panel-search').value='';$('#panel-per').value='';drawPanel();}if(e.target.closest('#panel-csv')){const rows=selectedPanelRows();if(!rows.length)return;csv('Panel_'+territory+'_'+panelTopic+'.csv',['Territorio','Tema','Indicador','PER','Valor reportado','Periodo o estado','Fuente','Página PDF'],rows.map(i=>[territoryName(),i.topic,i.name,i.kind,i.value||'',i.period||i.status,i.doc||'Anexo Indicadores Buitrera',i.page]));}});

document.addEventListener('click',e=>{if(e.target.closest('#view-interactive'))selectMapView('interactivo');if(e.target.closest('#view-originals'))selectMapView('originales');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
render();
})();
